const PAGE="<!doctype html><html lang=\"en\"><head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width, initial-scale=1, viewport-fit=cover\"><meta name=\"theme-color\" content=\"#0d1714\"><meta name=\"description\" content=\"Spectra FieldLink off-grid hunting communication\"><title>Spectra FieldLink</title><link rel=\"manifest\" href=\"/manifest.webmanifest\"><link rel=\"icon\" href=\"/icon.svg\" type=\"image/svg+xml\"><link rel=\"stylesheet\" href=\"https://unpkg.com/leaflet@1.9.4/dist/leaflet.css\"><style>\n:root{--bg:#0d1714;--panel:#172620;--deep:#101d18;--stroke:#31463a;--txt:#f1f8ec;--muted:#9aaf9f;--lime:#b7ea84;--orange:#f1c27f}*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--txt);font:14px system-ui,-apple-system,Segoe UI,sans-serif}button,input{font:inherit}button{cursor:pointer}button:disabled{opacity:.45;cursor:default}a{color:var(--lime)}.wrap{max-width:1100px;margin:auto;padding:20px 17px 104px}.head{display:flex;align-items:center;justify-content:space-between;gap:10px}.brand{display:flex;align-items:center;gap:10px;font-size:16px;font-weight:900;letter-spacing:.06em}.symbol{display:grid;place-items:center;width:40px;height:40px;border-radius:12px;background:var(--lime);color:#16301e;font-size:26px}.eyebrow{font-size:10px;color:var(--muted);font-weight:800;letter-spacing:.13em}.badge{background:#3d3022;color:var(--orange);border:1px solid #645036;font-size:10px;font-weight:900;padding:8px 10px;border-radius:40px;white-space:nowrap}h1{font-size:27px;letter-spacing:-.04em;margin:22px 0 2px}h2{font-size:16px;margin:0}h3{font-size:14px;margin:0}.subtitle{color:var(--muted);margin:0 0 18px;font-size:12px}.stats{display:grid;grid-template-columns:repeat(3,1fr);gap:8px;margin:14px 0}.stat,.panel{background:var(--panel);border:1px solid var(--stroke);border-radius:14px;padding:13px}.stat .k{font-size:10px;color:var(--muted);letter-spacing:.08em;text-transform:uppercase}.stat .v{margin-top:5px;font-weight:800;font-size:13px;min-height:20px}.section{display:none}.section.active{display:block}.bar{display:flex;align-items:center;justify-content:space-between;gap:10px;margin:16px 0 9px}.muted{color:var(--muted)}.note{font-size:12px;color:var(--muted);line-height:1.55}.warn{color:var(--orange)}.mode{display:flex;gap:4px;padding:4px;background:var(--deep);border:1px solid var(--stroke);border-radius:12px;margin:11px 0}.mode button{color:var(--muted);background:transparent;border:0;border-radius:9px;flex:1;padding:11px;font-size:12px;font-weight:800}.mode button.active{color:#172c1b;background:var(--lime)}.grid3{display:grid;grid-template-columns:repeat(3,1fr);gap:8px}.grid2{display:grid;grid-template-columns:repeat(2,1fr);gap:8px}.btn,.quick{background:var(--panel);border:1px solid var(--stroke);border-radius:11px;padding:12px 9px;color:var(--txt);font-weight:750;font-size:12px;min-height:43px}.btn.primary{background:var(--lime);border-color:var(--lime);color:#142d1b}.quick{text-align:left;padding:14px 10px;font-size:12px}.quick:active,.btn:active{transform:scale(.98)}.maparea{position:relative}.map{width:100%;height:clamp(330px,52vh,560px);border:1px solid var(--stroke);border-radius:15px;background:#2b4539;overflow:hidden}.mapfooter{position:absolute;bottom:11px;left:10px;right:10px;display:flex;justify-content:space-between;z-index:600;pointer-events:none}.mapfooter button,.mapfooter span{background:#12231ff0;color:#f0f6ef;border:1px solid #52735e;border-radius:10px;padding:9px 11px;font-size:11px;font-weight:750;pointer-events:auto}.panel{margin:11px 0}.panel p{margin:9px 0}.entry{display:flex;align-items:center;justify-content:space-between;gap:9px;padding:11px 0;border-bottom:1px solid var(--stroke)}.entry:last-child{border:0}.input{width:100%;padding:13px;border:1px solid var(--stroke);border-radius:10px;background:var(--deep);color:var(--txt);margin:5px 0}.compose{display:flex;gap:8px}.compose input{flex:1;min-width:0}.messages{height:290px;overflow-y:auto;display:flex;flex-direction:column;gap:10px;padding:10px 1px}.bubble{max-width:90%;align-self:flex-start;background:#30493a;padding:11px 13px;border-radius:12px;overflow-wrap:anywhere}.bubble.mine{align-self:flex-end;background:#3a6248}.bubble small{display:block;margin-top:5px;color:#cfddd0;font-size:10px}.teamcard{display:flex;gap:12px;align-items:center}.avatar{height:42px;width:42px;border-radius:12px;background:#3a6049;color:var(--lime);display:grid;place-items:center;font-weight:900}.teamcard .grow{flex:1}.teamcard strong{display:block;margin-bottom:4px}.teamcard small{color:var(--muted)}.tabs{position:fixed;bottom:0;left:0;right:0;display:flex;justify-content:center;z-index:1200;background:#13211df4;border-top:1px solid var(--stroke);backdrop-filter:blur(10px);padding-bottom:env(safe-area-inset-bottom)}.tabs>div{width:min(100%,640px);display:grid;grid-template-columns:repeat(4,1fr)}.tabs button{border:0;background:transparent;color:var(--muted);padding:12px 0 11px;font-size:11px;font-weight:800}.tabs button.active{color:var(--lime)}.tabs button b{display:block;font-size:19px;margin-bottom:3px}.toast{position:fixed;z-index:3000;top:70px;left:50%;transform:translateX(-50%);display:none;background:#3e644a;border:1px solid var(--lime);color:white;border-radius:12px;padding:12px;max-width:85%;text-align:center;font-size:12px}.toast.show{display:block}.leaflet-container{background:#29443b}.leaflet-popup-content-wrapper,.leaflet-popup-tip{background:#1a3025;color:#fff}@media(min-width:780px){.desktop{display:grid;grid-template-columns:minmax(0,1.7fr) minmax(300px,1fr);gap:16px}.wrap{padding-top:30px}.map{height:580px}.stats{max-width:790px}.side .grid3{grid-template-columns:1fr}.side .grid2{grid-template-columns:1fr}h1{font-size:34px}}\n\n.overlay{position:fixed;inset:0;z-index:2400;background:#020807cc;display:flex;justify-content:center;align-items:flex-end;padding:12px 12px max(18px,env(safe-area-inset-bottom))}.overlay[hidden]{display:none}.sheet{background:#1b2c25;border:1px solid #4c7054;border-radius:20px;padding:20px;max-height:92vh;overflow:auto;width:min(100%,510px)}.sheet h2{margin:0}.fieldlabel{display:block;font-size:12px;font-weight:800;margin:13px 0 7px}.options{display:grid;grid-template-columns:repeat(5,1fr);gap:5px}.icon-choice{background:#11241d;border:1px solid #53745f;color:white;border-radius:12px;min-height:84px;padding:8px 2px;font-size:10px;display:flex;flex-direction:column;align-items:center;gap:7px;justify-content:center}.icon-choice span:first-child{font-size:22px}.icon-choice.selected{background:#375340;border:2px solid var(--lime)}.swatches{display:grid;grid-template-columns:repeat(8,1fr);gap:7px}.swatch{width:100%;aspect-ratio:1;border-radius:50%;border:2px solid #24372a}.swatch.selected{outline:3px solid white;outline-offset:2px}.actions{display:flex;gap:8px;margin-top:16px}.actions .btn{flex:1}.marker-row{display:flex;align-items:center;gap:6px;margin-top:8px}.marker-row .btn:first-child{flex:1;overflow:hidden;white-space:nowrap;text-overflow:ellipsis;text-align:left}.marker-row .small-btn{padding:8px 6px;min-height:42px;font-size:11px}.pin-bubble{height:42px;width:42px;background:var(--pin);border:2px solid white;border-radius:15px 15px 15px 3px;transform:rotate(-45deg);display:grid;place-items:center;box-shadow:0 3px 12px #0009}.pin-bubble span{transform:rotate(45deg);font-size:21px;white-space:nowrap;text-shadow:0 1px 2px #0008}.owner-note{font-size:11px;line-height:1.5;color:var(--muted);margin-top:13px}\n/* Hunter location and active alerts */\n.hunter-map-marker{position:relative;width:126px;height:95px;pointer-events:none;text-align:center}\n.hunter-name{position:absolute;top:0;left:0;right:0;display:inline-block;max-width:126px;overflow:hidden;white-space:nowrap;text-overflow:ellipsis;font:bold 12px/18px system-ui,sans-serif;color:white;background:#10211de6;border:1px solid #809989;box-shadow:0 2px 7px #0007;border-radius:7px;padding:2px 5px;letter-spacing:0}\n.hunter-figure{position:absolute;top:25px;left:39px;width:47px;height:63px;filter:drop-shadow(0 2px 3px #000b)}\n.hunter-badge{position:absolute;bottom:2px;left:38px;color:#f1f9ef;font:bold 9px system-ui;background:#1d2c23e8;border-radius:7px;padding:1px 5px}\n.hunter-map-marker.needs-help .hunter-name{background:#9d2019;color:#fff;border-color:#fff;animation:helpflash 0.85s steps(2,start) infinite}\n.hunter-map-marker.needs-help .hunter-figure{animation:helpflash 0.85s steps(2,start) infinite}\n@keyframes helpflash{0%,100%{opacity:1}50%{opacity:.25}}\n.help-bubble{border:1px solid #fc9386;background:#481d20;color:white;font-weight:850;border-radius:9px;padding:7px;margin-top:5px}\n .help-map-banner{margin:9px 0;padding:11px 13px;background:#70231f;border:1px solid #f09789;border-radius:12px;color:#fff;font-weight:850;font-size:12px;animation:helpflash 1.3s steps(2,start) infinite}.sos-button{background:#a12924!important;border-color:#f48b78!important;color:#fff!important}\n.sos-active{background:#b72f21!important;border-color:#ffbfaf!important;color:#fff!important;animation:helpflash 1s steps(2,start) infinite}\n.hunter-color-options{display:grid;grid-template-columns:repeat(8,1fr);gap:8px;margin-top:12px}\n.hunter-color-choice{width:100%;aspect-ratio:1;border-radius:50%;border:2px solid #23392d}\n.hunter-color-choice.selected{outline:3px solid white;outline-offset:2px}\n.sighting-alert-overlay{position:fixed;inset:0;z-index:3100;background:#071209dc;backdrop-filter:blur(6px);display:flex;align-items:center;justify-content:center;padding:15px}\n.sighting-alert-overlay[hidden]{display:none}\n.sighting-alert-box{width:min(100%,450px);border:2px solid #f1bd62;border-radius:22px;background:#192b21;padding:22px;text-align:center;box-shadow:0 20px 60px #000e}\n.sighting-alert-icon{font-size:64px;margin:12px 0}\n.sighting-alert-title{font-size:27px;font-weight:950;margin:8px 0}\n.sighting-alert-text{font-size:17px;margin:12px 0}\n.sighting-alert-actions{display:grid;grid-template-columns:1fr 1fr;gap:10px;margin-top:18px}\n.sighting-alert-actions .btn{min-height:55px}\n .map-switch{display:flex;background:#11221b;border:1px solid #375541;border-radius:12px;margin:6px 0 10px;padding:4px;gap:4px}.map-switch button{flex:1;border:0;background:transparent;border-radius:8px;color:#b5c5b9;font-weight:850;font-size:12px;padding:10px 3px}.map-switch button.selected{color:#192e1f;background:#b7ea84}.tile-note{font-size:11px;color:#b2c6b3;margin-top:8px}</style></head><body><div class=\"wrap\"><header class=\"head\"><div class=\"brand\"><span class=\"symbol\">⌁</span><span>SPECTRA <span style=\"color:var(--lime)\">FIELDLINK</span><span class=\"eyebrow\" style=\"display:block\">NORTHSTAR VENTURES</span></span></div><span class=\"badge\" id=\"stateBadge\">BETA · DEMO</span></header><h1>Stay connected. Off the grid.</h1><p class=\"subtitle\">One hunting team. One map. LoRa + cellular transport.</p>\n<div class=\"stats\"><div class=\"stat\"><div class=\"k\">Radio link</div><div class=\"v warn\">Awaiting M1</div></div><div class=\"stat\"><div class=\"k\">Internet</div><div class=\"v\" id=\"netState\">Checking...</div></div><div class=\"stat\"><div class=\"k\">Group</div><div class=\"v\" id=\"teamState\">Demo team</div></div></div>\n<div class=\"mode\" aria-label=\"Transport\"><button data-mode=\"auto\" class=\"active\">⇄ Auto</button><button data-mode=\"lora\">⌁ LoRa Only</button><button data-mode=\"cell\">◉ Cellular</button></div><p class=\"note\" id=\"modeNote\">Auto mode: uses internet now. Hardware LoRa bridge is not connected yet.</p>\n<section id=\"mapTab\" class=\"section active\"><div class=\"desktop\"><div><div class=\"bar\"><h2>Field map</h2><span id=\"mapStatus\" class=\"eyebrow\">ONLINE TILES · PREVIEW</span></div><div id=\"helpMapBanner\" class=\"help-map-banner\" hidden></div><div class=\"map-switch\" aria-label=\"Choose basemap\"><button class=\"selected\" data-mapmode=\"hybrid\">🛰️ Hybrid</button><button data-mapmode=\"satellite\">Satellite</button><button data-mapmode=\"street\">Road map</button></div><div class=\"maparea\"><div class=\"map\" id=\"map\"><div class=\"note\" style=\"padding:20px\">Loading map...</div></div><div class=\"mapfooter\"><button id=\"myGps\">◎ My GPS</button><span id=\"coordLabel\">54.55, -114.65</span></div></div><p class=\"note warn\">Imagery and marked roads are available online. Cutlines and ATV tracks may be visible in satellite photos even when they aren't mapped as roads. Offline downloadable map packages are still planned for Android.</p></div><div class=\"side\"><div class=\"bar\"><h2>Field tools</h2></div><div class=\"grid3\"><button id=\"markPin\" class=\"btn primary\">＋ Mark spot</button><button id=\"moveDemo\" class=\"btn\">↗ Move hunter</button><button id=\"both\" class=\"btn\">⌖ Show both</button></div><div class=\"grid2\" style=\"margin-top:8px\"><button id=\"needHelp\" class=\"btn sos-button\">🚨 NEED HELP</button><button id=\"clearHelp\" class=\"btn\" hidden>✓ I'm safe — clear help</button></div><div class=\"bar\"><h2>Quick messages</h2></div><div class=\"grid2 quickHolder\"></div><div class=\"panel\"><h3>Shared markers</h3><div class=\"note\" id=\"pins\">No pins yet. Mark a spot on the map.</div></div></div></div></section>\n<section id=\"chatTab\" class=\"section\"><div class=\"bar\"><h2>Team messages</h2><span class=\"eyebrow\" id=\"chatStatus\">SIMULATION</span></div><div class=\"panel\"><div class=\"note\" id=\"chatNotice\">Demo messages are not sent to real radios or users.</div><div id=\"messages\" class=\"messages\"></div><form id=\"chatForm\" class=\"compose\"><input id=\"draft\" class=\"input\" placeholder=\"Send a field message...\" maxlength=\"160\" required><button class=\"btn primary\" type=\"submit\">Send</button></form></div><div class=\"bar\"><h2>One-tap messages</h2></div><div class=\"grid2 quickHolder\"></div></section>\n<section id=\"teamTab\" class=\"section\"><div class=\"bar\"><h2>Hunting team</h2><span class=\"eyebrow\" id=\"teamSubtitle\">DEMO GROUP</span></div><div id=\"members\"></div><div class=\"panel\"><h3>Your hunter on the map</h3><p class=\"note\">Select your walking hunter's jacket colour. Your name displays above your character.</p><div id=\"hunterColors\" class=\"hunter-color-options\"></div><p class=\"note\" id=\"gpsLiveState\">Live location: not started</p><button id=\"gpsLiveButton\" class=\"btn primary\">Start live GPS sharing</button><p class=\"note\">When location permission is allowed, GPS updates automatically while FieldLink is open. Pauses when hidden; background Android support is still being built.</p></div><div class=\"panel\"><h3>Start a cellular-enabled team</h3><p class=\"note\">Create a private group and share its team ID and secret with your other hunter. Internet-connected members will share messages, GPS fixes and pins through Cloudflare. LoRa relaying needs the Android app and M1 devices.</p><input class=\"input\" id=\"teamTitle\" placeholder=\"Team name (e.g. November hunt)\" maxlength=\"45\"><button id=\"createTeam\" class=\"btn primary\">Create private team</button></div><div class=\"panel\"><h3>Join an existing team</h3><input class=\"input\" id=\"joinId\" autocomplete=\"off\" placeholder=\"Team ID\"><input class=\"input\" id=\"joinSecret\" autocomplete=\"off\" placeholder=\"Team secret\"><input class=\"input\" id=\"profileName\" maxlength=\"28\" placeholder=\"Display name (e.g. Hunter 2)\"><button class=\"btn\" id=\"joinTeam\">Join team</button></div><div class=\"panel\" id=\"invitePanel\" style=\"display:none\"><h3>Group invitation</h3><p class=\"note\">Only share this invite with trusted hunters. Anyone holding it can read and post to your group in this beta.</p><div id=\"inviteText\" class=\"note\" style=\"overflow-wrap:anywhere\"></div><button id=\"copyInvite\" class=\"btn\">Copy team invite</button><button id=\"leaveTeam\" class=\"btn\">Leave on this phone</button></div></section>\n<section id=\"settingsTab\" class=\"section\"><div class=\"bar\"><h2>FieldLink configuration</h2></div><div class=\"panel\"><div class=\"entry\"><div><b>ThinkNode M1</b><div class=\"note\">nRF52840 · 915 MHz · Bluetooth</div></div><span class=\"badge\">Not paired</span></div><div class=\"entry\"><div><b>Hybrid relay</b><div class=\"note\">LoRa-to-cellular bridging on Android</div></div><span class=\"badge\">Planned</span></div><div class=\"entry\"><div><b>Offline map packages</b><div class=\"note\">Download hunting areas on Android</div></div><span class=\"badge\">Planned</span></div><div class=\"entry\"><div><b>GPS location sharing</b><div class=\"note\">Tap My GPS; permission required</div></div><span class=\"eyebrow\">AVAILABLE</span></div><div class=\"entry\"><div><b>Installable preview</b><div class=\"note\">Add this website to your home screen</div></div><span class=\"eyebrow\">PWA</span></div></div><div class=\"panel\"><h3>Sighting notifications</h3><p class=\"note\">Cow moose, bull moose, and Need Help alerts from another hunter open a repeating in-app vibration alert until dismissed. Your phone/browser must allow vibration. Locked-phone notifications need native Android integration.</p><button class=\"btn primary\" id=\"testSighting\">Test alert</button><button class=\"btn\" id=\"enableNotify\">Enable browser notifications</button><p class=\"note\" id=\"notifyState\">Notifications are not configured.</p></div><div class=\"panel\"><h3>Backup your field history</h3><p class=\"note\">Saves the visible events as a JSON file, without your secret.</p><button id=\"backup\" class=\"btn\">Export history</button><button id=\"demoReset\" class=\"btn\">Return to demo</button></div><div class=\"panel\"><h3>Privacy & safety</h3><p class=\"note\">Team members explicitly enable location sharing. GPS broadcasts automatically while FieldLink is active and permission is granted. Location requests cannot wake a closed web app; contact positions may be stale. This beta uses a shared team secret, not independently verified user identities. LoRa is not functional yet. The service is not an emergency distress system or satellite communicator. Do not rely on it as your sole safety device.</p></div></section>\n</div><div class=\"tabs\"><div><button class=\"active\" data-tab=\"map\"><b>⌖</b>Map</button><button data-tab=\"chat\"><b>▤</b>Messages</button><button data-tab=\"team\"><b>♙</b>Team</button><button data-tab=\"settings\"><b>⚙</b>Setup</button></div></div><div class=\"toast\" id=\"toast\" role=\"status\"></div><div class=\"sighting-alert-overlay\" id=\"sightingAlert\" hidden role=\"alertdialog\" aria-modal=\"true\" aria-labelledby=\"sightingTitle\"><div class=\"sighting-alert-box\"><div class=\"eyebrow\" id=\"sightingEyebrow\">⚠ NEW MOOSE SIGHTING</div><div class=\"sighting-alert-icon\" id=\"sightingIcon\">🫎</div><div class=\"sighting-alert-title\" id=\"sightingTitle\">Moose spotted!</div><div class=\"sighting-alert-text\" id=\"sightingText\">New marker from another hunter</div><p class=\"note\" id=\"sightingFrom\"></p><div class=\"sighting-alert-actions\"><button id=\"dismissSighting\" class=\"btn\">Dismiss</button><button id=\"seeSighting\" class=\"btn primary\">View map</button></div><p class=\"note\">Vibration repeats while this app is active until dismissed (if supported by the phone).</p></div></div>\n<div id=\"pinModal\" class=\"overlay\" hidden role=\"dialog\" aria-modal=\"true\" aria-labelledby=\"pinTitle\"><div class=\"sheet\"><div class=\"bar\" style=\"margin-top:0\"><h2 id=\"pinTitle\">Mark sighting</h2><button class=\"btn\" type=\"button\" id=\"pinClose\">✕</button></div><p class=\"note\">Your team will see this marker, its icon and colour.</p><label for=\"pinName\" class=\"fieldlabel\">Marker name</label><input id=\"pinName\" class=\"input\" maxlength=\"80\" placeholder=\"Moose sighting\"><span class=\"fieldlabel\">Marker type</span><div id=\"pinIcons\" class=\"options\"></div><span class=\"fieldlabel\">Marker colour</span><div id=\"pinColors\" class=\"swatches\"></div><div class=\"actions\"><button type=\"button\" class=\"btn\" id=\"pinCancel\">Cancel</button><button type=\"button\" class=\"btn primary\" id=\"pinSave\">Save marker</button></div><p class=\"owner-note\">🔒 Only this browser can edit/delete markers it creates. Do not clear its app data if you need to keep ownership.</p></div></div><script src=\"https://unpkg.com/leaflet@1.9.4/dist/leaflet.js\"></script><script>\n(function(){\n'use strict';\nvar quicks=[['🦌','Deer spotted'],['↗','Heading your way'],['✋','Stay put'],['📍','Meet at marked spot'],['✓','All clear'],['⚠','Need assistance']];\nvar session=null,mode=localStorage.getItem('fieldlink_mode')||'auto',events=[],queue=[],map=null,rendered=[],demoPartner=[54.562,-114.639],demoMe=[54.557,-114.654],picked=null,device=localStorage.getItem('fieldlink_device')||crypto.randomUUID(),displayName=localStorage.getItem('fieldlink_name')||'Hunter 1';\nlocalStorage.setItem('fieldlink_device',device);\ntry{session=JSON.parse(localStorage.getItem('fieldlink_session')||'null')}catch(e){}\ntry{queue=JSON.parse(localStorage.getItem('fieldlink_queue')||'[]')}catch(e){}\n\nvar markerCaps={};try{markerCaps=JSON.parse(localStorage.getItem('fieldlink_caps')||'{}')}catch(e){}\nvar markerActions=[];try{markerActions=JSON.parse(localStorage.getItem('fieldlink_marker_actions')||'[]')}catch(e){}\nvar pinTypes=[['cow','Cow moose','🫎♀'],['bull','Bull moose','🫎♂'],['buck','Buck','🦌♂'],['doe','Doe','🦌♀'],['hunter','Hunter','🥾']];\nvar pinPalette=['#B7EA84','#F7B267','#F36C6C','#79B8FF','#B5A2FF','#FFFFFF','#F1D95C','#5ADBB5'];\nvar editingPin=null,selectedPinType='buck',selectedPinColor='#F7B267';\nfunction saveCaps(){localStorage.setItem('fieldlink_caps',JSON.stringify(markerCaps))}\nfunction saveMarkerActions(){localStorage.setItem('fieldlink_marker_actions',JSON.stringify(markerActions.slice(-150)))}\nfunction ownPin(e){return isDemo()?e.author===device:!!markerCaps[currentTeam()+':'+e.id]}\nfunction pinType(code){return pinTypes.find(x=>x[0]===code)||pinTypes[2]}\nfunction pinColor(c){return pinPalette.includes(c)?c:'#F7B267'}\nfunction secretPin(){return Array.from(crypto.getRandomValues(new Uint8Array(24)),x=>x.toString(16).padStart(2,'0')).join('')}\nvar demoEvents=[{id:'demo-message-1',author:'partner-demo',author_name:'Hunter 2',kind:'message',body:'I am at the north clearing. Good visibility.',created:Date.now()-180000},{id:'demo-pin-1',author:'partner-demo',author_name:'Hunter 2',kind:'pin',body:'North clearing',lat:54.562,lon:-114.639,created:Date.now()-120000}];\nfunction el(id){return document.getElementById(id)}function clear(node){while(node.firstChild)node.removeChild(node.firstChild)}function node(tag,cls,text){var e=document.createElement(tag);if(cls)e.className=cls;if(text!==undefined)e.textContent=text;return e}\nvar toastTimer;function toast(s){var e=el('toast');e.textContent=s;e.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(function(){e.classList.remove('show')},2900)}\nfunction isDemo(){return !session}\nfunction allEvents(){return (isDemo()?demoEvents:events.concat(queue)).slice().sort(function(a,b){return a.created-b.created}).filter(function(e,i,arr){return arr.findIndex(function(v){return v.id===e.id})===i}).map(function(e){var a=markerActions.find(x=>x.id===e.id);return a&&a.action==='update'?Object.assign({},e,{body:a.body,marker_icon:a.marker_icon,marker_color:a.marker_color}):e}).filter(function(e){return !markerActions.some(a=>a.id===e.id&&a.action==='delete')})}\nfunction currentTeam(){return session?session.team_id:'demo'}\nfunction normPoint(lat,lon){return typeof lat==='number'&&typeof lon==='number'&&Number.isFinite(lat)&&Number.isFinite(lon)&&Math.abs(lat)<=90&&Math.abs(lon)<=180}\nfunction sendAllowed(){if(mode==='lora'&&!isDemo()){toast('LoRa Bluetooth adapter is not connected yet');return false}if(!session){return true}return true}\nfunction setMode(x){mode=x;localStorage.setItem('fieldlink_mode',x);document.querySelectorAll('[data-mode]').forEach(function(b){b.classList.toggle('active',b.dataset.mode===x)});el('modeNote').textContent=x==='lora'?'LoRa-only mode: waiting for your ThinkNode M1 and native Android Bluetooth adapter.':x==='cell'?'Cellular mode: uses available phone internet. Does not require a LoRa radio.':'Auto: currently uses internet when available; LoRa bridging will activate after Android integration.';renderState()}\n\n/* User map identity and foreground GPS */\nvar walkerColor=localStorage.getItem('fieldlink_hunter_color')||'#B7EA84',liveGPS=localStorage.getItem('fieldlink_live_gps')!=='0',gpsWatcher=null,gpsLast=null,gpsSentAt=0,gpsSentCoords=null,gpsStatus='Not started';\nvar serverHunters=[],currentAlert=null,pendingAlerts=[],vibrateTimer=null,requestSeen=new Set();\ntry{requestSeen=new Set(JSON.parse(localStorage.getItem('fieldlink_seen_requests_'+currentTeam())||'[]'))}catch(e){}\nfunction htmlSafe(s){return String(s||'').replace(/[&<>\"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','\"':'&quot;',\"'\":'&#39;'}[c]))}\nfunction showAge(t){var sec=Math.max(0,Math.floor((Date.now()-t)/1000));if(sec<60)return 'Now';if(sec<3600)return Math.floor(sec/60)+'m ago';if(sec<86400)return Math.floor(sec/3600)+'h ago';return Math.floor(sec/86400)+'d ago'}\nfunction latestHunters(){\n var users={};allEvents().forEach(function(e){if(!['position','help','help_clear'].includes(e.kind))return;var h=users[e.author]||{author:e.author,author_name:e.author_name,hunter_color:walkerColor,created:0,help:false};\n h.author_name=e.author_name||h.author_name;if(e.hunter_color)h.hunter_color=e.hunter_color;\n if(normPoint(e.lat,e.lon)){h.lat=e.lat;h.lon=e.lon;h.created=e.created}\n if(e.kind==='help')h.help=true;if(e.kind==='help_clear')h.help=false;users[e.author]=h;\n });\n if(isDemo()){\n  users['partner-demo']=Object.assign(users['partner-demo']||{},{author:'partner-demo',author_name:'Hunter 2',lat:demoPartner[0],lon:demoPartner[1],hunter_color:'#ffb86b',created:Date.now()-10000,help:false});\n  users[device]=Object.assign(users[device]||{},{author:device,author_name:'You · DEMO',lat:demoMe[0],lon:demoMe[1],hunter_color:walkerColor,created:Date.now(),help:users[device]?.help||false});\n }\n if(gpsLast&&(!users[device]||gpsLast.time>(users[device].created||0))){users[device]=Object.assign(users[device]||{},{author:device,author_name:displayName+(isDemo()?' · DEMO':''),lat:gpsLast.lat,lon:gpsLast.lon,created:gpsLast.time,hunter_color:walkerColor,help:users[device]?.help||false})}\n serverHunters.forEach(function(p){if(!p||!p.author||isDemo())return;var h=users[p.author]||{author:p.author};h.author_name=p.author_name;h.hunter_color=p.hunter_color;h.lat=p.lat;h.lon=p.lon;h.created=p.location_at||0;h.help=p.needs_help===1;h.help_at=p.help_at;users[p.author]=h});\n queue.filter(function(e){return ['position','help','help_clear'].includes(e.kind)}).forEach(function(e){var h=users[e.author]||{author:e.author};h.author_name=e.author_name;if(e.hunter_color)h.hunter_color=e.hunter_color;if(normPoint(e.lat,e.lon)){h.lat=e.lat;h.lon=e.lon;h.created=e.created}if(e.kind==='help')h.help=true;if(e.kind==='help_clear')h.help=false;users[e.author]=h});\n return users;\n}\nfunction drawHunterColors(){\n var host=el('hunterColors');if(!host)return;clear(host);pinPalette.forEach(function(color){\n var b=node('button','hunter-color-choice'+(walkerColor===color?' selected':''));b.type='button';b.style.background=color;b.setAttribute('aria-label','Hunter color '+color);b.addEventListener('click',function(){walkerColor=color;localStorage.setItem('fieldlink_hunter_color',color);drawHunterColors();renderAll();if(gpsLast&&!isDemo()&&liveGPS)send('position','Hunter colour update',gpsLast.lat,gpsLast.lon,{hunter_color:walkerColor});});host.appendChild(b)});\n}\nfunction hunterIcon(person){\n var color=pinPalette.includes(person.hunter_color)?person.hunter_color:'#B7EA84';\n var title=htmlSafe(person.author_name||'Hunter');var recent=Date.now()-(person.created||0)<90000;var label=(person.help?'🚨 HELP · ':'')+title;\n var svg='<svg viewBox=\"0 0 48 70\" width=\"47\" height=\"66\" aria-hidden=\"true\"><path d=\"M12 17 L32 17 L37 21 L9 21Z\" fill=\"#343e26\" stroke=\"#0b1710\" stroke-width=\"2\"/><path d=\"M16 10 Q23 5 31 10 L33 17 L14 17Z\" fill=\"'+color+'\" stroke=\"#16251b\" stroke-width=\"2\"/><circle cx=\"24\" cy=\"26\" r=\"8\" fill=\"#dfb88d\" stroke=\"#463425\" stroke-width=\"1.5\"/><path d=\"M15 36 L29 34 L36 46 L29 53 L17 53 L12 45Z\" fill=\"'+color+'\" stroke=\"#101e17\" stroke-width=\"2\"/><rect x=\"9\" y=\"37\" width=\"10\" height=\"15\" rx=\"3\" fill=\"#74563e\" stroke=\"#1d241d\" stroke-width=\"1.5\"/><path d=\"M17 39 L10 49 M33 39 L40 47\" stroke=\"#dfb88d\" stroke-width=\"5\" stroke-linecap=\"round\"/><path d=\"M20 52 L15 67 M29 52 L35 65\" stroke=\"#444a36\" stroke-width=\"6\" stroke-linecap=\"round\"/><path d=\"M11 66 L20 66 M32 66 L40 66\" stroke=\"#1b231b\" stroke-width=\"5\" stroke-linecap=\"round\"/></svg>';\n return L.divIcon({className:'',html:'<div class=\"hunter-map-marker'+(person.help?' needs-help':'')+'\"><div class=\"hunter-name\">'+label+'</div><div class=\"hunter-figure\">'+svg+'</div><div class=\"hunter-badge\">'+(person.help?'SOS':recent?'LIVE':'LAST')+'</div></div>',iconSize:[126,95],iconAnchor:[63,91],popupAnchor:[0,-79]});\n}\nfunction geoDistance(a,b){const rad=Math.PI/180,dx=(a.lat-b.lat)*111200,dy=(a.lon-b.lon)*111200*Math.cos(a.lat*rad);return Math.sqrt(dx*dx+dy*dy)}\nfunction publishFix(pos,forced){\n if(!pos||!Number.isFinite(pos.coords.latitude)||!Number.isFinite(pos.coords.longitude))return;\n gpsLast={lat:pos.coords.latitude,lon:pos.coords.longitude,time:Date.now()};\n if(isDemo()){demoMe=[gpsLast.lat,gpsLast.lon];renderMap();return}\n if(!session||mode==='lora')return;\n if(!forced&&Date.now()-gpsSentAt<45000&&gpsSentCoords&&geoDistance(gpsLast,gpsSentCoords)<30){renderMap();return}\n gpsSentAt=Date.now();gpsSentCoords={lat:gpsLast.lat,lon:gpsLast.lon};\n send('position','GPS update',gpsLast.lat,gpsLast.lon,{hunter_color:walkerColor});\n}\nfunction startLocation(){\n if(!navigator.geolocation){gpsStatus='GPS unavailable';renderState();return}\n if(!liveGPS||document.visibilityState!=='visible')return;\n if(gpsWatcher!==null)return;\n gpsStatus='Acquiring GPS…';renderState();\n gpsWatcher=navigator.geolocation.watchPosition(function(p){gpsStatus='Sharing · '+showAge(Date.now());publishFix(p,false);renderState()},function(err){gpsStatus='GPS denied / unavailable: '+err.message;renderState();if(err.code===1){liveGPS=false;localStorage.setItem('fieldlink_live_gps','0');stopLocation()}},{enableHighAccuracy:true,maximumAge:10000,timeout:18000});\n}\nfunction stopLocation(){if(gpsWatcher!==null){navigator.geolocation.clearWatch(gpsWatcher);gpsWatcher=null}}\nfunction setLocationSharing(on){\n liveGPS=!!on;localStorage.setItem('fieldlink_live_gps',liveGPS?'1':'0');if(liveGPS)startLocation();else{stopLocation();gpsStatus='Paused'}renderState();\n}\nfunction freshGPS(){if(!navigator.geolocation){toast('GPS unavailable');return}navigator.geolocation.getCurrentPosition(function(pos){publishFix(pos,true);if(map)map.setView([pos.coords.latitude,pos.coords.longitude],15);toast('Fresh GPS location sent')},function(err){toast('GPS unavailable: '+err.message)},{enableHighAccuracy:true,maximumAge:0,timeout:15000})}\nfunction seenRequests(){try{return JSON.parse(localStorage.getItem('fieldlink_seen_requests_'+currentTeam())||'[]')}catch(e){return []}}\nfunction consumeLocationRequests(received){\n if(isDemo()||document.visibilityState!=='visible'||!liveGPS)return;\n var seen=new Set(seenRequests());var changed=false;\n for(var e of received){if(e.kind!=='location_request'||e.author===device||e.body!==device||!e.created||Date.now()-e.created>180000||seen.has(e.id))continue;\n seen.add(e.id);changed=true;freshGPS();\n }\n if(changed)localStorage.setItem('fieldlink_seen_requests_'+currentTeam(),JSON.stringify([...seen].slice(-200)));\n}\nfunction askHunterLocation(id,name){\n if(!session){toast('Demo: live location requests need two joined phones');return}\n if(id===device){freshGPS();return}\n send('location_request',id,null,null);toast('Location requested from '+name+'. Requires their app to be active with GPS enabled.');\n}\nfunction currentHelp(){return !!latestHunters()[device]?.help}\nfunction toggleHelp(){\n if(!isDemo()&&mode==='lora'){toast('LoRa transport is not connected yet');return}\n var now=currentHelp();var kind=now?'help_clear':'help',loc=gpsLast||latestHunters()[device],lat=loc&&normPoint(loc.lat,loc.lon)?loc.lat:null,lon=loc&&normPoint(loc.lat,loc.lon)?loc.lon:null;\n if(now){send('help_clear','Safe now',null,null,{hunter_color:walkerColor});toast('Help alert cleared');}\n else if(confirm('Send NEED HELP to everyone in your hunting team?')){send('help','NEED HELP',lat,lon,{hunter_color:walkerColor});if(!normPoint(lat,lon))freshGPS();toast('Help alert sent. Not a substitute for emergency satellite communication.')}\n}\nfunction renderHelp(){\n var help=currentHelp();el('needHelp').classList.toggle('sos-active',help);el('needHelp').textContent=help?'🚨 HELP ACTIVE':'🚨 NEED HELP';el('clearHelp').hidden=!help;el('clearHelp').disabled=!help;\n var active=Object.values(latestHunters()).filter(x=>x.help),banner=el('helpMapBanner');\n if(active.length){banner.hidden=false;banner.textContent='🚨 NEED HELP: '+active.map(x=>x.author_name+(normPoint(x.lat,x.lon)?' — location on map':' — LOCATION UNKNOWN')).join(' · ')}\n else{banner.hidden=true;banner.textContent=''}\n}\nfunction alertSeenKey(){return 'fieldlink_sighting_seen_'+currentTeam()}\nfunction seenAlertIds(){try{return JSON.parse(localStorage.getItem(alertSeenKey())||'[]')}catch(e){return []}}\nfunction acknowledgeAlert(id){var seen=seenAlertIds();if(!seen.includes(id)){seen.push(id);localStorage.setItem(alertSeenKey(),JSON.stringify(seen.slice(-300)))}}\nfunction detectAlerts(list){\n if(!session)return;var seen=new Set(seenAlertIds()),first=[];\n for(var e of list){if(e.author===device||!e.created||e.created<Date.now()-3*3600000||seen.has(e.id))continue;\n if(!(e.kind==='help'||(e.kind==='pin'&&['cow','bull'].includes(e.marker_icon))))continue;\n seen.add(e.id);acknowledgeAlert(e.id);first.push(e)}\n if(first.length){pendingAlerts.push(...first);if(!currentAlert)presentAlert()}\n}\nfunction pulseVibration(){if(currentAlert&&document.visibilityState==='visible'&&navigator.vibrate)try{navigator.vibrate([400,120,400,120,650])}catch(e){}}\nfunction presentAlert(){\n if(currentAlert||!pendingAlerts.length)return;currentAlert=pendingAlerts.shift();\n var urgent=currentAlert.kind==='help';\n el('sightingEyebrow').textContent=urgent?'🚨 HUNTER NEEDS HELP':'⚠ NEW MOOSE SIGHTING';\n el('sightingIcon').textContent=urgent?'🚨':currentAlert.marker_icon==='bull'?'🫎♂':'🫎♀';\n el('sightingTitle').textContent=urgent?'Hunter needs help!':currentAlert.marker_icon==='bull'?'Bull moose spotted!':'Cow moose spotted!';\n el('sightingText').textContent=currentAlert.body;\n el('sightingFrom').textContent='From '+currentAlert.author_name;\n el('sightingAlert').hidden=false;pulseVibration();clearInterval(vibrateTimer);vibrateTimer=setInterval(pulseVibration,2200);\n if('Notification' in window&&Notification.permission==='granted'&&document.visibilityState==='visible')try{new Notification(el('sightingTitle').textContent,{body:currentAlert.author_name+': '+currentAlert.body,tag:currentAlert.id,requireInteraction:true})}catch(e){}\n}\nfunction dismissAlert(view){\n var old=currentAlert;if(navigator.vibrate)try{navigator.vibrate(0)}catch(e){}\n clearInterval(vibrateTimer);vibrateTimer=null;currentAlert=null;el('sightingAlert').hidden=true;\n if(view&&old){showTab('map');var h=latestHunters()[old.author];var loc=normPoint(old.lat,old.lon)?old:h;if(loc&&normPoint(loc.lat,loc.lon)&&map)map.setView([loc.lat,loc.lon],15);else toast('Location not yet reported')}\n if(pendingAlerts.length)presentAlert();\n}\nfunction testAlert(){pendingAlerts.push({id:'test-'+Date.now(),kind:'pin',marker_icon:'bull',body:'Test sighting · this phone only',author_name:'Test Hunter',created:Date.now()});if(!currentAlert)presentAlert()}\nasync function enableNotifications(){if(!('Notification'in window)){toast('Browser notification API unavailable');return}try{var status=await Notification.requestPermission();el('notifyState').textContent='Browser notifications: '+status+'. Locked phone alerting requires Android app.'}catch(e){toast('Notifications unsupported here')}}\n\nfunction showTab(t){document.querySelectorAll('.section').forEach(function(s){s.classList.toggle('active',s.id===t+'Tab')});document.querySelectorAll('[data-tab]').forEach(function(b){b.classList.toggle('active',b.dataset.tab===t)});if(t==='map'&&map)setTimeout(function(){map.invalidateSize()},70);if(t==='team')renderTeam();if(t==='chat')renderMessages()}\nfunction renderState(){el('netState').textContent=navigator.onLine?'Available':'Offline';el('netState').style.color=navigator.onLine?'var(--lime)':'var(--orange)';el('teamState').textContent=isDemo()?'Demo team':session.team_id;el('stateBadge').textContent=isDemo()?'BETA · DEMO':'BETA · CELLULAR';el('chatStatus').textContent=isDemo()?'SIMULATION':'CELLULAR BETA';el('chatNotice').textContent=isDemo()?'Demo messages are only visible on this device.':'Messages sync using phone internet. LoRa bridging is not active until the Android adapter is implemented.';el('teamSubtitle').textContent=isDemo()?'DEMO GROUP':'PRIVATE TEAM';el('moveDemo').disabled=!isDemo();el('demoReset').textContent=isDemo()?'Reset demo':'Return to demo';el('gpsLiveState').textContent='Live GPS: '+(liveGPS?gpsStatus:'Off');el('gpsLiveButton').textContent=liveGPS?'Pause live GPS':'Start live GPS sharing';}\nvar basemapMode=localStorage.getItem('fieldlink_map_mode')||'hybrid',basemapLayers={},basemapActive=[];\nfunction chooseBasemap(mode){\n if(!map)return;basemapMode=['hybrid','satellite','street'].includes(mode)?mode:'hybrid';localStorage.setItem('fieldlink_map_mode',basemapMode);\n basemapActive.forEach(x=>map.removeLayer(x));basemapActive=[];\n var base=basemapMode==='street'?basemapLayers.street:basemapLayers.imagery;\n base.addTo(map);basemapActive.push(base);\n if(basemapMode==='hybrid'){basemapLayers.transport.addTo(map);basemapLayers.places.addTo(map);basemapActive.push(basemapLayers.transport,basemapLayers.places)}\n document.querySelectorAll('[data-mapmode]').forEach(b=>b.classList.toggle('selected',b.dataset.mapmode===basemapMode));\n el('mapStatus').textContent=(basemapMode==='street'?'ROAD MAP':basemapMode==='satellite'?'SATELLITE':'HYBRID')+' · LOADING';\n}\nfunction initMap(){\n if(typeof L==='undefined'){el('map').textContent='Map library did not load. Reconnect and refresh to retry.';return}\n map=L.map('map',{zoomControl:false}).setView([54.557,-114.647],12);\n L.control.zoom({position:'topright'}).addTo(map);\n basemapLayers.street=L.tileLayer('https://tile.openstreetmap.org/{z}/{x}/{y}.png',{attribution:'&copy; OpenStreetMap contributors',maxZoom:19,subdomains:[]});\n basemapLayers.imagery=L.tileLayer('https://server.arcgisonline.com/ArcGIS/rest/services/World_Imagery/MapServer/tile/{z}/{y}/{x}',{attribution:'Imagery &copy; Esri and imagery contributors',maxZoom:19,maxNativeZoom:19});\n basemapLayers.transport=L.tileLayer('https://server.arcgisonline.com/ArcGIS/rest/services/Reference/World_Transportation/MapServer/tile/{z}/{y}/{x}',{attribution:'Roads &copy; Esri, HERE, Garmin and contributors',maxZoom:19,maxNativeZoom:19,opacity:1});\n basemapLayers.places=L.tileLayer('https://server.arcgisonline.com/ArcGIS/rest/services/Reference/World_Boundaries_and_Places/MapServer/tile/{z}/{y}/{x}',{attribution:'Labels &copy; Esri',maxZoom:19,maxNativeZoom:19,opacity:1});\n Object.entries(basemapLayers).forEach(([name,layer])=>{\n  layer.on('load',function(){if((basemapMode==='street'&&name==='street')||(basemapMode!=='street'&&name==='imagery')){el('mapStatus').textContent=(basemapMode==='street'?'ROAD MAP':basemapMode==='satellite'?'SATELLITE':'HYBRID')+' · LOADED';el('mapStatus').style.color='var(--lime)'}});\n  layer.on('tileerror',function(){if((basemapMode==='street'&&name==='street')||(basemapMode!=='street'&&name==='imagery')){el('mapStatus').textContent='MAP IMAGERY UNAVAILABLE · RETRY';el('mapStatus').style.color='var(--orange)'}})\n });\n document.querySelectorAll('[data-mapmode]').forEach(b=>b.addEventListener('click',()=>chooseBasemap(b.dataset.mapmode)));\n el('mapStatus').addEventListener('click',function(){basemapActive.forEach(x=>x.redraw());toast('Retrying map images')});\n chooseBasemap(basemapMode);\n map.on('click',function(e){picked=[e.latlng.lat,e.latlng.lng];el('coordLabel').textContent='Pin: '+picked[0].toFixed(4)+', '+picked[1].toFixed(4);toast('Point selected — tap Mark spot')});\n renderMap()\n}\n\nfunction drawPinOptions(){\n var icons=el('pinIcons'),colors=el('pinColors');clear(icons);clear(colors);\n pinTypes.forEach(function(t){var b=node('button','icon-choice'+(selectedPinType===t[0]?' selected':''));b.type='button';b.appendChild(node('span','',t[2]));b.appendChild(node('span','',t[1]));b.setAttribute('aria-label',t[1]);b.addEventListener('click',function(){selectedPinType=t[0];drawPinOptions()});icons.appendChild(b)});\n pinPalette.forEach(function(c){var b=node('button','swatch'+(selectedPinColor===c?' selected':''));b.type='button';b.style.background=c;b.setAttribute('aria-label','Colour '+c);b.addEventListener('click',function(){selectedPinColor=c;drawPinOptions()});colors.appendChild(b)});\n}\nfunction openPinEditor(e){\n if(e&&!ownPin(e)){toast('Only the creator can edit this marker');return}\n editingPin=e||null;selectedPinType=e&&e.marker_icon||'buck';selectedPinColor=pinColor(e&&e.marker_color);\n el('pinTitle').textContent=e?'Edit your marker':'New shared marker';el('pinName').value=e?e.body:'';\n drawPinOptions();el('pinModal').hidden=false;setTimeout(function(){el('pinName').focus()},100)\n}\nfunction closePinEditor(){el('pinModal').hidden=true;editingPin=null}\nfunction setMarkerAction(action){markerActions=markerActions.filter(x=>x.id!==action.id);markerActions.push(action);saveMarkerActions()}\nasync function savePinEditor(){\n var body=el('pinName').value.trim();if(!body){toast('Name your marker');return}\n var edit=editingPin;closePinEditor();\n if(edit){\n   if(isDemo()){Object.assign(edit,{body:body,marker_icon:selectedPinType,marker_color:selectedPinColor});renderAll();toast('Demo marker updated');return}\n   var token=markerCaps[currentTeam()+':'+edit.id];if(!token){toast('Marker key missing');return}\n   setMarkerAction({id:edit.id,action:'update',token:token,body:body,marker_icon:selectedPinType,marker_color:selectedPinColor});\n   renderAll();await flushMarkerActions();await refresh();toast('Marker saved or queued');return\n }\n var c=picked||[map.getCenter().lat,map.getCenter().lng];picked=null;\n send('pin',body,c[0],c[1],{marker_icon:selectedPinType,marker_color:selectedPinColor,marker_token:secretPin()});\n}\nasync function deletePin(e){\n if(!ownPin(e)){toast('Only the original creator can delete this marker');return}\n if(!confirm('Remove \"'+e.body+'\" from the shared map?'))return;\n if(isDemo()){demoEvents=demoEvents.filter(x=>x.id!==e.id);renderAll();toast('Demo marker removed');return}\n var token=markerCaps[currentTeam()+':'+e.id];if(!token){toast('Marker key missing');return}\n if(queue.some(x=>x.id===e.id)){queue=queue.filter(x=>x.id!==e.id);saveQueue()}\n else setMarkerAction({id:e.id,token:token,action:'delete'});\n renderAll();await flushMarkerActions();await refresh();toast('Marker removed or queued')\n}\nasync function flushMarkerActions(){\n if(!session||!navigator.onLine||mode==='lora')return;\n for(var a of markerActions.slice()){\n  try{await req('/api/markers?team='+encodeURIComponent(session.team_id),{method:'POST',headers:auth(),body:JSON.stringify(a)});markerActions=markerActions.filter(x=>x!==a);saveMarkerActions();if(a.action==='delete'){delete markerCaps[currentTeam()+':'+a.id];saveCaps()}}\n  catch(e){console.warn('Marker sync queued:',e.message);break}\n }\n}\nfunction markerSymbol(e){var p=pinType(e.marker_icon),color=pinColor(e.marker_color);return L.divIcon({className:'',html:'<div class=\"pin-bubble\" style=\"--pin:'+color+'\"><span>'+p[2]+'</span></div>',iconSize:[44,47],iconAnchor:[14,43]})}\nfunction renderMap(){if(!map)return;rendered.forEach(function(m){map.removeLayer(m)});rendered=[];var latest=latestHunters();\nObject.values(latest).filter(p=>normPoint(p.lat,p.lon)).forEach(function(p){var m=L.marker([p.lat,p.lon],{icon:hunterIcon(p)}),panel=node('div');panel.appendChild(node('strong','',p.author_name));panel.appendChild(node('div','note',p.help?'🚨 NEEDS HELP — '+showAge(p.created):'Last GPS: '+showAge(p.created)));if(p.author!==device){var btn=node('button','btn','Request updated location');btn.addEventListener('click',function(){askHunterLocation(p.author,p.author_name)});panel.appendChild(btn)}else{var btn=node('button','btn','Update my GPS');btn.addEventListener('click',freshGPS);panel.appendChild(btn)}m.bindPopup(panel);m.addTo(map);rendered.push(m)});\nallEvents().filter(function(e){return e.kind==='pin'&&normPoint(e.lat,e.lon)}).forEach(function(e){var p=L.marker([e.lat,e.lon],{icon:markerSymbol(e)}),pop=node('div');pop.appendChild(node('strong','',pinType(e.marker_icon)[1]+' · '+e.body));pop.appendChild(node('div','',e.author_name));if(ownPin(e)){var controls=node('div');controls.style.marginTop='8px';var eb=node('button','btn','Edit');eb.addEventListener('click',function(){map.closePopup();openPinEditor(e)});var db=node('button','btn','Delete');db.style.marginLeft='6px';db.addEventListener('click',function(){map.closePopup();deletePin(e)});controls.append(eb,db);pop.appendChild(controls)}else pop.appendChild(node('small','', 'Owner controlled'));p.bindPopup(pop);p.addTo(map);rendered.push(p)});\nvar markers=allEvents().filter(e=>e.kind==='pin'),holder=el('pins');clear(holder);if(!markers.length)holder.textContent='No pins yet. Mark a spot on the map.';markers.slice(-12).reverse().forEach(function(p){var row=node('div','marker-row'),btn=node('button','btn',pinType(p.marker_icon)[2]+' '+p.body+' · '+p.author_name);btn.addEventListener('click',function(){showTab('map');if(map&&normPoint(p.lat,p.lon))map.setView([p.lat,p.lon],15)});row.appendChild(btn);if(ownPin(p)){var eb=node('button','btn small-btn','Edit');eb.addEventListener('click',function(){openPinEditor(p)});row.appendChild(eb);var db=node('button','btn small-btn','Delete');db.addEventListener('click',function(){deletePin(p)});row.appendChild(db)}holder.appendChild(row)})}\nfunction showBoth(){if(!map)return;var pts=Object.values(latestHunters()).filter(e=>normPoint(e.lat,e.lon)).map(e=>[e.lat,e.lon]);if(pts.length)map.fitBounds(pts,{padding:[55,55],maxZoom:14});else toast('Enable live GPS to show hunter positions')}\nfunction renderMessages(){var host=el('messages');clear(host);var a=allEvents().filter(function(e){return e.kind==='message'});if(!a.length){host.appendChild(node('div','note','No messages yet. Send your first message.'));return}a.forEach(function(e){var b=node('div','bubble'+(e.author===device?' mine':''));b.appendChild(node('span','',e.body));var time=new Date(e.created).toLocaleTimeString([],{hour:'numeric',minute:'2-digit'});b.appendChild(node('small','',e.author_name+' · '+time+(e.pending?' · Queued':'')));host.appendChild(b)});host.scrollTop=host.scrollHeight}\nfunction renderTeam(){var host=el('members');clear(host);var latest=latestHunters(),users=new Map;if(isDemo()){users.set(device,'You · DEMO');users.set('partner-demo','Hunter 2 · DEMO')}else{users.set(device,displayName);allEvents().forEach(e=>users.set(e.author,e.author_name))}users.forEach(function(name,id){var p=latest[id],c=node('div','panel teamcard'),avatar=node('div','avatar',id===device?'YOU':name.slice(0,2).toUpperCase());avatar.style.background=p&&p.hunter_color||'#3a6049';avatar.style.color='#0d1714';c.appendChild(avatar);var g=node('div','grow');g.appendChild(node('strong','',name+(p?.help?' 🚨 NEED HELP':'')));g.appendChild(node('small','',p&&p.created?'Last GPS '+showAge(p.created):'No reported GPS location'));c.appendChild(g);if(id!==device){var btn=node('button','btn', '↻ GPS');btn.title='Request a fresh GPS fix while their app is active';btn.addEventListener('click',()=>askHunterLocation(id,name));c.appendChild(btn)}host.appendChild(c)});el('invitePanel').style.display=session?'block':'none';if(session)el('inviteText').textContent='Team ID: '+session.team_id+' | Secret: '+session.secret}\nfunction renderAll(){renderState();renderMessages();renderTeam();renderMap();renderHelp()}\nfunction saveQueue(){localStorage.setItem('fieldlink_queue',JSON.stringify(queue.slice(-200)))}\nfunction auth(){return {'Content-Type':'application/json','Authorization':'Bearer '+session.secret}}\nasync function req(path,opt){var res=await fetch(path,opt);var data;try{data=await res.json()}catch(e){throw Error('Invalid server response')}if(!res.ok)throw Error(data.error||'Request failed');return data}\nasync function refresh(){if(!session||!navigator.onLine)return;try{await flush();await flushMarkerActions();var v=await req('/api/events?team='+encodeURIComponent(session.team_id),{headers:auth(),cache:'no-store'});var incoming=v.events||[];events=incoming;serverHunters=v.hunters||[];detectAlerts(incoming);consumeLocationRequests(incoming);renderAll()}catch(e){el('netState').textContent='Connection issue';}}\nasync function flush(){if(!session||!navigator.onLine||mode==='lora'||!queue.length)return;var list=queue.slice();for(var i=0;i<list.length;i++){var p=list[i];try{await req('/api/events?team='+encodeURIComponent(session.team_id),{method:'POST',headers:auth(),body:JSON.stringify(p)});queue=queue.filter(function(e){return e.id!==p.id});saveQueue()}catch(e){break}}}\nasync function send(kind,body,lat,lon,extra){if(!sendAllowed())return;var e=Object.assign({id:crypto.randomUUID(),author:device,author_name:displayName,kind:kind,body:String(body).trim().slice(0,160),lat:lat,lon:lon,created:Date.now()},extra||{});if(!e.body)return;if(kind==='pin'){e.marker_token=e.marker_token||secretPin();markerCaps[currentTeam()+':'+e.id]=e.marker_token;saveCaps()}if(['position','help','help_clear'].includes(kind)){e.hunter_color=e.hunter_color||walkerColor}if(isDemo()){demoEvents.push(e);toast('Demo event added (not transmitted)');renderAll();return}queue.push(Object.assign({pending:true},e));saveQueue();renderAll();if(mode==='lora')return;await flush();await refresh();if(queue.some(function(v){return v.id===e.id}))toast('Offline — queued for later internet delivery');else toast('Shared with your cellular team')}\nfunction markSpot(){if(!map){toast('Map unavailable');return}openPinEditor(null)}\nfunction getGPS(){setLocationSharing(true);freshGPS()}\nasync function createTeam(){var title=el('teamTitle').value.trim()||'FieldLink Team';displayName=el('profileName').value.trim()||displayName;localStorage.setItem('fieldlink_name',displayName);try{var r=await req('/api/team',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({title:title})});session={team_id:r.team_id,secret:r.secret,title:title};localStorage.setItem('fieldlink_session',JSON.stringify(session));events=[];serverHunters=[];queue=[];saveQueue();renderAll();refresh();if(liveGPS)startLocation();toast('Private team created. Share your invite with the second hunter.')}catch(e){toast('Could not create team: '+e.message)}}\nasync function joinTeam(){var id=el('joinId').value.trim().toUpperCase(),secret=el('joinSecret').value.trim();if(!id||!secret){toast('Enter team ID and secret');return}try{var v=await req('/api/events?team='+encodeURIComponent(id),{headers:{'Authorization':'Bearer '+secret}});displayName=el('profileName').value.trim()||'Hunter 2';localStorage.setItem('fieldlink_name',displayName);session={team_id:id,secret:secret,title:v.team};localStorage.setItem('fieldlink_session',JSON.stringify(session));queue=[];saveQueue();events=v.events||[];serverHunters=v.hunters||[];renderAll();if(liveGPS)startLocation();toast('Joined private team')}catch(e){toast('Could not join: '+e.message)}}\nfunction demoReset(){stopLocation();currentAlert=null;pendingAlerts=[];clearInterval(vibrateTimer);el('sightingAlert').hidden=true;session=null;events=[];serverHunters=[];queue=[];saveQueue();localStorage.removeItem('fieldlink_session');demoEvents=demoEvents.slice(0,2);renderAll();showTab('map');toast('Back in local simulation')}\nfunction download(){var data=JSON.stringify({app:'Spectra FieldLink',version:1,team:currentTeam(),exported:new Date().toISOString(),events:allEvents().map(function(e){var r=Object.assign({},e);delete r.marker_token;return r})},null,2);var a=document.createElement('a'),url=URL.createObjectURL(new Blob([data],{type:'application/json'}));a.href=url;a.download='spectra-fieldlink-history.json';a.click();setTimeout(function(){URL.revokeObjectURL(url)},1000)}\nfunction install(){if('serviceWorker'in navigator)navigator.serviceWorker.register('/sw.js').catch(function(){})}\ndocument.querySelectorAll('[data-tab]').forEach(function(b){b.addEventListener('click',function(){showTab(b.dataset.tab)})});\ndocument.querySelectorAll('[data-mode]').forEach(function(b){b.addEventListener('click',function(){setMode(b.dataset.mode)})});\ndocument.querySelectorAll('.quickHolder').forEach(function(host){quicks.forEach(function(q){var b=node('button','quick',q[0]+'  '+q[1]);b.addEventListener('click',function(){send('message',q[1])});host.appendChild(b)})});\nel('chatForm').addEventListener('submit',function(e){e.preventDefault();send('message',el('draft').value);el('draft').value=''});\nel('markPin').addEventListener('click',markSpot);el('needHelp').addEventListener('click',toggleHelp);el('clearHelp').addEventListener('click',toggleHelp);el('gpsLiveButton').addEventListener('click',function(){setLocationSharing(!liveGPS)});el('testSighting').addEventListener('click',testAlert);el('enableNotify').addEventListener('click',enableNotifications);el('dismissSighting').addEventListener('click',function(){dismissAlert(false)});el('seeSighting').addEventListener('click',function(){dismissAlert(true)});el('pinClose').addEventListener('click',closePinEditor);el('pinCancel').addEventListener('click',closePinEditor);el('pinSave').addEventListener('click',savePinEditor);el('pinModal').addEventListener('click',function(e){if(e.target===el('pinModal'))closePinEditor()});el('myGps').addEventListener('click',getGPS);\nel('moveDemo').addEventListener('click',function(){if(!isDemo())return;demoPartner=[demoPartner[0]+(Math.random()-.5)*.009,demoPartner[1]+(Math.random()-.5)*.009];renderMap();toast('Hunter 2 moved (simulation)')});\nel('both').addEventListener('click',showBoth);el('createTeam').addEventListener('click',createTeam);el('joinTeam').addEventListener('click',joinTeam);el('leaveTeam').addEventListener('click',demoReset);el('demoReset').addEventListener('click',demoReset);el('backup').addEventListener('click',download);\nel('copyInvite').addEventListener('click',async function(){if(!session)return;var s='Spectra FieldLink team: '+session.team_id+' | secret: '+session.secret+' | '+location.origin;try{await navigator.clipboard.writeText(s);toast('Team invite copied')}catch(e){toast('Copy unavailable — select invite text instead')}});\nwindow.addEventListener('online',function(){renderState();refresh()});window.addEventListener('offline',renderState);document.addEventListener('visibilitychange',function(){if(document.visibilityState==='visible'){if(liveGPS)startLocation();refresh();if(currentAlert)pulseVibration()}else{stopLocation();if(navigator.vibrate)navigator.vibrate(0)}});\nsetMode(mode);initMap();drawHunterColors();renderAll();if(session){refresh();if(liveGPS)startLocation()}setInterval(refresh,7000);install();\n})();\n</script></body></html>";

const HEADERS={"content-type":"application/json; charset=utf-8","Cache-Control":"no-store","X-Content-Type-Options":"nosniff","Referrer-Policy":"strict-origin-when-cross-origin","X-Frame-Options":"DENY"};
function json(data,status=200){return new Response(JSON.stringify(data),{status,headers:HEADERS})}
function fail(message,status=400){return json({error:message},status)}
function hex(bytes){return Array.from(bytes).map(x=>x.toString(16).padStart(2,"0")).join("")}
async function digest(s){return hex(new Uint8Array(await crypto.subtle.digest("SHA-256",new TextEncoder().encode(s))))}
function token(){return hex(crypto.getRandomValues(new Uint8Array(24)))}
async function auth(request,env,team){if(!team||!/^[A-Z0-9]{8,16}$/.test(team))return null;const token=(request.headers.get("Authorization")||"").replace(/^Bearer\s+/i,"").trim();if(!/^[a-f0-9]{48}$/.test(token))return null;const hash=await digest(token);const a=await env.DB.prepare("SELECT m.id AS member_id,m.hunter_name,m.hunter_color,m.role,t.team_id,t.title FROM hunter_members m JOIN teams t ON t.team_id=m.team WHERE m.team=? AND m.login_hash=?").bind(team,hash).first();return a||null}
function securityHeaders(extra){return {...HEADERS,...extra}}
export default {async fetch(request,env){
const url=new URL(request.url),path=url.pathname;
if(path==="/health")return json({ok:true,app:"Spectra FieldLink",cellular:true,lora:"pending native Android",hybrid:"planned"});
if(path==="/manifest.webmanifest")return new Response(JSON.stringify({name:"Spectra FieldLink",short_name:"FieldLink",start_url:"/",scope:"/",display:"standalone",background_color:"#0d1714",theme_color:"#0d1714",icons:[{src:"/icon.svg",sizes:"any",type:"image/svg+xml",purpose:"any maskable"}]}),{headers:securityHeaders({"content-type":"application/manifest+json"})});
if(path==="/icon.svg")return new Response('<svg xmlns="http://www.w3.org/2000/svg" width="192" height="192" viewBox="0 0 192 192"><rect width="192" height="192" rx="34" fill="#10251a"/><path d="M34 94l32-25 26 50 31-55 35 30" fill="none" stroke="#b7ea84" stroke-width="16" stroke-linecap="round" stroke-linejoin="round"/></svg>',{headers:{"content-type":"image/svg+xml"}});
if(path==="/sw.js")return new Response('const C="fieldlink-shell-v9";self.addEventListener("install",e=>e.waitUntil(caches.open(C).then(c=>c.addAll(["/","/icon.svg"]))));self.addEventListener("fetch",e=>{let u=new URL(e.request.url);if(e.request.method!=="GET"||u.pathname.startsWith("/api/")||u.pathname==="/health"||u.origin!==location.origin)return;if(u.pathname==="/"){e.respondWith(fetch(e.request).then(r=>{let c=r.clone();caches.open(C).then(x=>x.put(e.request,c));return r}).catch(()=>caches.match("/")));}});',{headers:{"content-type":"application/javascript","Cache-Control":"no-cache"}});
if(path==="/"||path==="/index.html")return new Response(PAGE,{headers:{"content-type":"text/html; charset=utf-8","Cache-Control":"no-cache","X-Content-Type-Options":"nosniff","Referrer-Policy":"strict-origin-when-cross-origin","X-Frame-Options":"DENY"}});

if(path==="/api/invite-info"&&request.method==="GET"){
 const code=String(url.searchParams.get("code")||"");
 if(!/^[a-f0-9]{48}$/.test(code))return fail("Invitation not valid",404);
 const i=await env.DB.prepare("SELECT t.title,i.role FROM hunter_invites i JOIN teams t ON t.team_id=i.team WHERE i.code_hash=? AND i.used_at IS NULL AND i.expires>?").bind(await digest(code),Date.now()).first();
 if(!i)return fail("This invitation has expired or has already been used",410);
 return json({valid:true,team_name:i.title,role:i.role});
}
if(path==="/api/register"&&request.method==="POST"){
 let data;try{data=await request.json()}catch{return fail("Invalid registration")}
 const code=String(data.code||""),name=String(data.name||"").trim(),color=String(data.color||"");
 if(!/^[a-f0-9]{48}$/.test(code)||name.length<2||name.length>28||!["#B7EA84","#F7B267","#F36C6C","#79B8FF","#B5A2FF","#FFFFFF","#F1D95C","#5ADBB5"].includes(color))return fail("Enter your name and choose a hunter colour");
 const hash=await digest(code),now=Date.now(),login=token(),loginHash=await digest(login),id=token().slice(0,24);
 const stmt=env.DB.prepare("INSERT INTO hunter_members(id,team,hunter_name,hunter_color,login_hash,invite_hash,role,created,last_seen) SELECT ?,i.team,?,?,?,i.code_hash,i.role,?,? FROM hunter_invites i WHERE i.code_hash=? AND i.used_at IS NULL AND i.expires>?").bind(id,name,color,loginHash,now,now,hash,now);
 let result;
 try{result=await stmt.run()}catch(e){return fail("Invitation has already been redeemed",410)}
 if(result.meta?.changes!==1)return fail("Invitation is expired or already used",410);
 await env.DB.prepare("UPDATE hunter_invites SET used_at=? WHERE code_hash=? AND used_at IS NULL").bind(now,hash).run();
 const member=await env.DB.prepare("SELECT t.title,t.team_id,m.role FROM hunter_members m JOIN teams t ON t.team_id=m.team WHERE m.id=?").bind(id).first();
 return json({member_id:id,token:login,member_name:name,member_color:color,role:member.role,team_id:member.team_id,title:member.title},201);
}
if(path==="/api/invite"&&request.method==="POST"){
 const team=url.searchParams.get("team"),member=await auth(request,env,team);
 if(!member)return fail("Hunter sign-in required",401);
 const code=token(),now=Date.now(),expires=now+7*24*60*60*1000;
 await env.DB.prepare("INSERT INTO hunter_invites(code_hash,team,created_by,role,created,expires,used_at) VALUES (?,?,?,?,?,?,NULL)").bind(await digest(code),team,member.member_id,"hunter",now,expires).run();
 return json({invite_url:url.origin+"/?invite="+code,expires,team_name:member.title});
}
if(path==="/api/member-color"&&request.method==="POST"){
 const team=url.searchParams.get("team"),member=await auth(request,env,team);
 if(!member)return fail("Hunter sign-in required",401);
 let data;try{data=await request.json()}catch{return fail("Invalid body")}
 const color=String(data.color||"");
 if(!["#B7EA84","#F7B267","#F36C6C","#79B8FF","#B5A2FF","#FFFFFF","#F1D95C","#5ADBB5"].includes(color))return fail("Invalid colour");
 await env.DB.prepare("UPDATE hunter_members SET hunter_color=? WHERE id=? AND team=?").bind(color,member.member_id,team).run();
 await env.DB.prepare("UPDATE hunter_presence SET hunter_color=? WHERE author=? AND team=?").bind(color,member.member_id,team).run();
 return json({ok:true,color});
}
if(path==="/api/events"&&(request.method==="GET"||request.method==="POST")){
 const team=url.searchParams.get("team"),account=await auth(request,env,team);
 if(!account)return fail("Team ID or secret incorrect",401);
 if(request.method==="GET"){
  const items=await env.DB.prepare("SELECT id,author,author_name,kind,body,lat,lon,created,marker_icon,marker_color,hunter_color FROM events WHERE team=? AND deleted=0 ORDER BY created DESC LIMIT 200").bind(team).all();
  const hunters=await env.DB.prepare("SELECT author,author_name,hunter_color,lat,lon,location_at,last_contact,needs_help,help_at FROM hunter_presence WHERE team=? LIMIT 50").bind(team).all();
  const members=await env.DB.prepare("SELECT id,hunter_name,hunter_color,role,created,last_seen FROM hunter_members WHERE team=? LIMIT 50").bind(team).all();
  return json({team:account.title,events:(items.results||[]).reverse(),hunters:hunters.results||[],members:members.results||[],you:account.member_id});
 }
 let data;try{data=await request.json()}catch{return fail("Invalid JSON")}
 const id=String(data.id||""),author=account.member_id,name=account.hunter_name,kind=String(data.kind||""),body=String(data.body||"").trim();const markerIcon=String(data.marker_icon||"buck"),markerColor=String(data.marker_color||"#F7B267"),markerToken=String(data.marker_token||"");
 if(!/^[\w-]{8,64}$/.test(id)||!/^[\w-]{8,64}$/.test(author)||name.length<1||name.length>28||!["message","pin","position","help","help_clear","location_request"].includes(kind)||!body||body.length>160)return fail("Invalid event");
 const geo=(typeof data.lat==="number"&&typeof data.lon==="number"&&Number.isFinite(data.lat)&&Number.isFinite(data.lon)&&Math.abs(data.lat)<=90&&Math.abs(data.lon)<=180);const hunterColor=account.hunter_color;
 if(["position","pin"].includes(kind)&&!geo)return fail("GPS coordinates required");
 if(kind==="pin"&&(!/^[a-f0-9]{48}$/.test(markerToken)||!["cow","bull","buck","doe","hunter"].includes(markerIcon)||!["#B7EA84","#F7B267","#F36C6C","#79B8FF","#B5A2FF","#FFFFFF","#F1D95C","#5ADBB5"].includes(markerColor)))return fail("Invalid marker settings or owner key");
 let created=Date.now();
 await env.DB.prepare("INSERT OR IGNORE INTO events(id,team,author,author_name,kind,body,lat,lon,created,delete_hash,marker_icon,marker_color,hunter_color) VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?)").bind(id,team,author,name,kind,body,geo?data.lat:null,geo?data.lon:null,created,kind==="pin"?await digest(markerToken):null,kind==="pin"?markerIcon:null,kind==="pin"?markerColor:null,hunterColor).run();
 if(["position","help","help_clear"].includes(kind)){
  const needs=kind==="help"?1:0;
  const sql="INSERT INTO hunter_presence(team,author,author_name,hunter_color,lat,lon,location_at,last_contact,needs_help,help_at) VALUES (?,?,?,?,?,?,?,?,?,?) ON CONFLICT(team,author) DO UPDATE SET author_name=excluded.author_name,hunter_color=excluded.hunter_color,lat=COALESCE(excluded.lat,hunter_presence.lat),lon=COALESCE(excluded.lon,hunter_presence.lon),location_at=COALESCE(excluded.location_at,hunter_presence.location_at),last_contact=excluded.last_contact,needs_help=CASE WHEN ?='position' THEN hunter_presence.needs_help ELSE excluded.needs_help END,help_at=CASE WHEN ?='position' THEN hunter_presence.help_at ELSE excluded.help_at END";
  await env.DB.prepare(sql).bind(team,author,name,hunterColor,geo?data.lat:null,geo?data.lon:null,geo?created:null,created,needs,kind==="help"?created:null,kind,kind).run();
 }
 return json({ok:true,id});
}

if(path==="/api/markers"&&request.method==="POST"){
 const team=url.searchParams.get("team"),account=await auth(request,env,team);
 if(!account)return fail("Team ID or secret incorrect",401);
 let data;try{data=await request.json()}catch{return fail("Invalid JSON")}
 const id=String(data.id||""),token=String(data.token||""),action=String(data.action||"");
 if(!/^[\w-]{8,64}$/.test(id)||!/^[a-f0-9]{48}$/.test(token)||!["delete","update"].includes(action))return fail("Invalid marker request");
 const hash=await digest(token);
 const rec=await env.DB.prepare("SELECT id,author,delete_hash,deleted FROM events WHERE team=? AND id=? AND kind='pin'").bind(team,id).first();
 if(!rec)return fail("Marker not found",404);
 if(rec.author!==account.member_id)return fail("Only the hunter who created this marker may modify it",403);
 if(rec.deleted===1)return json({ok:true,deleted:true});
 if(action==="delete"){
  await env.DB.prepare("UPDATE events SET deleted=1 WHERE id=? AND team=? AND author=? AND deleted=0").bind(id,team,account.member_id).run();
  return json({ok:true,deleted:true})
 }
 const body=String(data.body||"").trim(),icon=String(data.marker_icon||""),color=String(data.marker_color||"");
 if(!body||body.length>80||!["cow","bull","buck","doe","hunter"].includes(icon)||!["#B7EA84","#F7B267","#F36C6C","#79B8FF","#B5A2FF","#FFFFFF","#F1D95C","#5ADBB5"].includes(color))return fail("Invalid marker details");
 await env.DB.prepare("UPDATE events SET body=?,marker_icon=?,marker_color=? WHERE id=? AND team=? AND author=? AND deleted=0").bind(body,icon,color,id,team,account.member_id).run();
 return json({ok:true,updated:true})
}
return fail("Not found",404)
}};
